# openEMS far-field pattern (auto-generated by FluxPCB)
# nf2ff box around the radiator; produces 3D pattern + gain.
import openems, numpy as np
unit = 1e-3
FDTD = openems.OpenEMS(unit=unit, end_criteria=3000)
FDTD.SetGaussPulse(6e9, f0=3e9)
csx = FDTD.csx
# single-sided PCB edge radiator stub model (replace with board geometry)
sub = csx.AddMaterial(" sub", epsilon=4.4)
sub.AddBox(xs=-20, ys=-20, zs=0, xe=20, ye=20, ze=1.6)
gnd = csx.AddMetal(" gnd"); gnd.AddBox(xs=-20, ys=-20, zs=0, xe=20, ye=20, ze=0)
stub = csx.AddMetal(" stub"); stub.AddBox(xs=-1, ys=0, zs=1.6, xe=1, ye=15, ze=1.635)
FDTD.nf2ff.CalcPort = ["1"]
angles = np.arange(0, 181, 5)
FDTD.Run("sim_ff", verbose=1)
print("pattern/gain: sim_ff/nf2ff_*.h5")
